import { Types } from 'mongoose';
import { SchoolSettings, } from '../models/SchoolSettings.model.js';
import { School } from '../models/School.model.js';
import { AcademicSession } from '../models/AcademicSession.model.js';
import { GradingScale } from '../models/GradingScale.model.js';
import { AuditLog } from '../models/AuditLog.model.js';
import { ApiError } from '../utils/apiError.js';
import { logger } from '../utils/logger.js';
export class SchoolSettingsService {
    /**
     * Helper: Record configuration audit event
     */
    static async logAudit(schoolId, action, targetResource, actorId, metadata, ipAddress, userAgent) {
        try {
            await AuditLog.create({
                schoolId,
                action,
                targetResource,
                actorId: actorId ? new Types.ObjectId(actorId) : undefined,
                metadata,
                ipAddress,
                userAgent,
                timestamp: new Date(),
            });
        }
        catch (err) {
            logger.warn(`[AuditLog] Failed to record settings audit log: ${err.message}`);
        }
    }
    /**
     * Retrieves or initializes complete centralized settings for a school
     */
    static async getOrCreateSettings(schoolId) {
        const sId = new Types.ObjectId(schoolId);
        let settings = await SchoolSettings.findOne({ schoolId: sId });
        if (!settings) {
            // Find school to inherit baseline info
            const school = await School.findById(sId);
            const activeSession = await AcademicSession.findOne({
                schoolId: sId,
                isCurrent: true,
                isDeleted: false,
            });
            const schoolName = school?.name || 'Academic Institution';
            const code = school?.code || 'SCH-001';
            const email = school?.email || 'admin@school.example.com';
            const timezone = school?.timezone || 'UTC';
            const currency = school?.currency || 'USD';
            settings = await SchoolSettings.create({
                schoolId: sId,
                profile: {
                    schoolName,
                    shortName: schoolName.split(' ')[0],
                    code,
                    email,
                    phone: school?.phone || '',
                    website: '',
                    description: 'Institutional Management System',
                    address: {
                        street: school?.address?.street || '',
                        city: school?.address?.city || '',
                        state: school?.address?.state || '',
                        postalCode: school?.address?.postalCode || '',
                        country: school?.address?.country || '',
                    },
                },
                branding: {
                    logoUrl: school?.logo || '',
                    faviconUrl: '',
                    primaryColor: '#2563eb',
                    secondaryColor: '#0f172a',
                    reportCardHeader: `${schoolName} - Official Student Transcript`,
                    emailFooterText: `Official notification from ${schoolName}`,
                },
                regional: {
                    timezone,
                    dateFormat: school?.settings?.dateFormat || 'YYYY-MM-DD',
                    timeFormat: '12h',
                    weekStartDay: 'monday',
                    currencyCode: currency,
                    currencySymbol: currency === 'USD' ? '$' : currency === 'EUR' ? '€' : currency === 'GBP' ? '£' : '$',
                },
                academic: {
                    activeSessionId: activeSession?._id,
                    workingDays: ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'],
                    holidays: [],
                    termsCount: 2,
                },
                attendance: {
                    supportedStatuses: ['present', 'absent', 'late', 'leave'],
                    defaultWorkingDays: ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'],
                    lateArrivalThresholdMinutes: 15,
                    absenceThresholdForAlert: 3,
                    minimumAttendancePercentage: school?.settings?.attendanceThreshold || 75,
                    dailyAlertEnabled: true,
                },
                fees: {
                    defaultDueGraceDays: school?.settings?.feeDueGraceDays || 7,
                    reminderScheduleDays: [7, 3, 1],
                    invoicePrefix: 'INV',
                    paymentInstructions: 'Please clear fees via bank transfer or direct school counter payment.',
                    receiptNotes: 'Receipt generated by EduManage SMS.',
                    allowPartialPayments: true,
                    lateFeeEnabled: false,
                    lateFeeAmount: 0,
                },
                notifications: {
                    attendanceAlertDefault: true,
                    feeReminderDefault: true,
                    homeworkReminderDefault: true,
                    examNoticeDefault: true,
                    resultNoticeDefault: true,
                    schoolAnnouncementDefault: true,
                    quietHoursEnabled: false,
                    quietHoursStart: '22:00',
                    quietHoursEnd: '07:00',
                },
            });
            logger.info(`[SchoolSettings] Initialized default configuration for school: ${sId}`);
        }
        return settings;
    }
    /**
     * Update School Profile & Contact details
     */
    static async updateProfile(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        if (input.schoolName)
            settings.profile.schoolName = input.schoolName;
        if (input.shortName !== undefined)
            settings.profile.shortName = input.shortName;
        if (input.email)
            settings.profile.email = input.email;
        if (input.phone !== undefined)
            settings.profile.phone = input.phone;
        if (input.website !== undefined)
            settings.profile.website = input.website;
        if (input.description !== undefined)
            settings.profile.description = input.description;
        if (input.address) {
            settings.profile.address = { ...settings.profile.address, ...input.address };
        }
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        // Synchronize authoritative School document
        await School.findByIdAndUpdate(sId, {
            $set: {
                ...(input.schoolName && { name: input.schoolName }),
                ...(input.email && { email: input.email }),
                ...(input.phone !== undefined && { phone: input.phone }),
                ...(input.address && { address: settings.profile.address }),
            },
        });
        await this.logAudit(sId, 'UPDATE_SCHOOL_PROFILE', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Update Branding settings (Colors, Logos, Letterheads)
     */
    static async updateBranding(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        if (input.logoUrl !== undefined)
            settings.branding.logoUrl = input.logoUrl;
        if (input.faviconUrl !== undefined)
            settings.branding.faviconUrl = input.faviconUrl;
        if (input.primaryColor)
            settings.branding.primaryColor = input.primaryColor;
        if (input.secondaryColor)
            settings.branding.secondaryColor = input.secondaryColor;
        if (input.reportCardHeader !== undefined)
            settings.branding.reportCardHeader = input.reportCardHeader;
        if (input.emailFooterText !== undefined)
            settings.branding.emailFooterText = input.emailFooterText;
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        if (input.logoUrl !== undefined) {
            await School.findByIdAndUpdate(sId, { $set: { logo: input.logoUrl } });
        }
        await this.logAudit(sId, 'UPDATE_SCHOOL_BRANDING', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Update Regional & Localization Settings
     */
    static async updateRegional(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        if (input.timezone)
            settings.regional.timezone = input.timezone;
        if (input.dateFormat)
            settings.regional.dateFormat = input.dateFormat;
        if (input.timeFormat)
            settings.regional.timeFormat = input.timeFormat;
        if (input.weekStartDay)
            settings.regional.weekStartDay = input.weekStartDay;
        if (input.currencyCode)
            settings.regional.currencyCode = input.currencyCode;
        if (input.currencySymbol)
            settings.regional.currencySymbol = input.currencySymbol;
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        // Synchronize school document without modifying historical payments
        await School.findByIdAndUpdate(sId, {
            $set: {
                ...(input.timezone && { timezone: input.timezone, 'settings.timezone': input.timezone }),
                ...(input.currencyCode && { currency: input.currencyCode, 'settings.currency': input.currencyCode }),
                ...(input.dateFormat && { 'settings.dateFormat': input.dateFormat }),
            },
        });
        await this.logAudit(sId, 'UPDATE_SCHOOL_REGIONAL', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Update Academic Calendar & Policy Settings
     */
    static async updateAcademic(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        if (input.activeSessionId) {
            const session = await AcademicSession.findOne({
                _id: new Types.ObjectId(input.activeSessionId),
                schoolId: sId,
                isDeleted: false,
            });
            if (!session) {
                throw ApiError.badRequest('Referenced academic session not found in this school.');
            }
            // Atomically set isCurrent: true on referenced session and isCurrent: false on others
            await AcademicSession.updateMany({ schoolId: sId, _id: { $ne: session._id } }, { $set: { isCurrent: false, status: 'completed' } });
            session.isCurrent = true;
            session.status = 'active';
            await session.save();
            settings.academic.activeSessionId = session._id;
            await School.findByIdAndUpdate(sId, { $set: { 'settings.academicYear': session.name } });
        }
        if (input.workingDays)
            settings.academic.workingDays = input.workingDays;
        if (input.termsCount)
            settings.academic.termsCount = input.termsCount;
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'UPDATE_SCHOOL_ACADEMIC', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Add Academic Holiday to Calendar
     */
    static async addHoliday(schoolId, input, actorId) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        const holiday = {
            _id: new Types.ObjectId(),
            name: input.name,
            startDate: new Date(input.startDate),
            endDate: new Date(input.endDate),
            type: input.type,
            description: input.description,
        };
        settings.academic.holidays.push(holiday);
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'ADD_ACADEMIC_HOLIDAY', 'SchoolSettings', actorId, holiday);
        return settings;
    }
    /**
     * Update Academic Holiday
     */
    static async updateHoliday(schoolId, holidayId, input, actorId) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        const holiday = settings.academic.holidays.find((h) => h._id.toString() === holidayId);
        if (!holiday) {
            throw ApiError.notFound('Holiday not found.');
        }
        holiday.name = input.name;
        holiday.startDate = new Date(input.startDate);
        holiday.endDate = new Date(input.endDate);
        if (input.type)
            holiday.type = input.type;
        if (input.description !== undefined)
            holiday.description = input.description;
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'UPDATE_ACADEMIC_HOLIDAY', 'SchoolSettings', actorId, { holidayId, ...input });
        return settings;
    }
    /**
     * Delete Academic Holiday
     */
    static async deleteHoliday(schoolId, holidayId, actorId) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        settings.academic.holidays = settings.academic.holidays.filter((h) => h._id.toString() !== holidayId);
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'DELETE_ACADEMIC_HOLIDAY', 'SchoolSettings', actorId, { holidayId });
        return settings;
    }
    /**
     * Update Attendance Policies
     */
    static async updateAttendancePolicy(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        if (input.supportedStatuses)
            settings.attendance.supportedStatuses = input.supportedStatuses;
        if (input.defaultWorkingDays)
            settings.attendance.defaultWorkingDays = input.defaultWorkingDays;
        if (input.lateArrivalThresholdMinutes !== undefined) {
            settings.attendance.lateArrivalThresholdMinutes = input.lateArrivalThresholdMinutes;
        }
        if (input.absenceThresholdForAlert !== undefined) {
            settings.attendance.absenceThresholdForAlert = input.absenceThresholdForAlert;
        }
        if (input.minimumAttendancePercentage !== undefined) {
            settings.attendance.minimumAttendancePercentage = input.minimumAttendancePercentage;
            await School.findByIdAndUpdate(sId, {
                $set: { 'settings.attendanceThreshold': input.minimumAttendancePercentage },
            });
        }
        if (input.dailyAlertEnabled !== undefined) {
            settings.attendance.dailyAlertEnabled = input.dailyAlertEnabled;
        }
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'UPDATE_ATTENDANCE_POLICY', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Update Fee and Invoice Settings
     */
    static async updateFeePolicy(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        if (input.defaultDueGraceDays !== undefined) {
            settings.fees.defaultDueGraceDays = input.defaultDueGraceDays;
            await School.findByIdAndUpdate(sId, {
                $set: { 'settings.feeDueGraceDays': input.defaultDueGraceDays },
            });
        }
        if (input.reminderScheduleDays)
            settings.fees.reminderScheduleDays = input.reminderScheduleDays;
        if (input.invoicePrefix)
            settings.fees.invoicePrefix = input.invoicePrefix;
        if (input.paymentInstructions !== undefined) {
            settings.fees.paymentInstructions = input.paymentInstructions;
        }
        if (input.receiptNotes !== undefined)
            settings.fees.receiptNotes = input.receiptNotes;
        if (input.allowPartialPayments !== undefined) {
            settings.fees.allowPartialPayments = input.allowPartialPayments;
        }
        if (input.lateFeeEnabled !== undefined)
            settings.fees.lateFeeEnabled = input.lateFeeEnabled;
        if (input.lateFeeAmount !== undefined)
            settings.fees.lateFeeAmount = input.lateFeeAmount;
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'UPDATE_FEE_POLICY', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Update Notification Settings Defaults
     */
    static async updateNotificationSettings(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        settings.notifications = { ...settings.notifications, ...input };
        settings.updatedBy = actorId ? new Types.ObjectId(actorId) : undefined;
        await settings.save();
        await this.logAudit(sId, 'UPDATE_NOTIFICATION_SETTINGS', 'SchoolSettings', actorId, input, ip, ua);
        return settings;
    }
    /**
     * Get Academic Calendar view
     */
    static async getAcademicCalendar(schoolId) {
        const sId = new Types.ObjectId(schoolId);
        const settings = await this.getOrCreateSettings(sId);
        const [sessions, activeSession] = await Promise.all([
            AcademicSession.find({ schoolId: sId, isDeleted: false }).sort({ startDate: -1 }),
            AcademicSession.findOne({ schoolId: sId, isCurrent: true, isDeleted: false }),
        ]);
        return {
            activeSession,
            sessions,
            workingDays: settings.academic.workingDays,
            holidays: settings.academic.holidays,
            timezone: settings.regional.timezone,
        };
    }
    /**
     * Get or initialize Grading Scale
     */
    static async getGradingPolicy(schoolId) {
        const sId = new Types.ObjectId(schoolId);
        let scale = await GradingScale.findOne({ schoolId: sId, isDefault: true, isDeleted: false });
        if (!scale) {
            scale = await GradingScale.findOne({ schoolId: sId, isDeleted: false });
        }
        if (!scale) {
            // Create standard default grading scale
            scale = await GradingScale.create({
                schoolId: sId,
                name: 'Standard Institutional Scale',
                description: 'Default percentage-based letter grading with grade points',
                isDefault: true,
                bands: [
                    { grade: 'A+', minPercentage: 90, maxPercentage: 100, gradePoint: 4.0, isPassing: true, description: 'Outstanding' },
                    { grade: 'A', minPercentage: 80, maxPercentage: 89, gradePoint: 3.7, isPassing: true, description: 'Excellent' },
                    { grade: 'B', minPercentage: 70, maxPercentage: 79, gradePoint: 3.0, isPassing: true, description: 'Good' },
                    { grade: 'C', minPercentage: 60, maxPercentage: 69, gradePoint: 2.0, isPassing: true, description: 'Satisfactory' },
                    { grade: 'D', minPercentage: 50, maxPercentage: 59, gradePoint: 1.0, isPassing: true, description: 'Pass' },
                    { grade: 'F', minPercentage: 0, maxPercentage: 49, gradePoint: 0.0, isPassing: false, description: 'Fail' },
                ],
            });
        }
        return scale;
    }
    /**
     * Update Grading Policy & Validate Boundaries (Strictly prospective; never mutates published results)
     */
    static async updateGradingPolicy(schoolId, input, actorId, ip, ua) {
        const sId = new Types.ObjectId(schoolId);
        // Validate boundaries: No overlapping bands, minPercentage <= maxPercentage
        const sortedBands = [...input.bands].sort((a, b) => b.minPercentage - a.minPercentage);
        for (let i = 0; i < sortedBands.length; i++) {
            const band = sortedBands[i];
            if (band.minPercentage > band.maxPercentage) {
                throw ApiError.badRequest(`Grade band "${band.grade}" has minPercentage greater than maxPercentage.`);
            }
            if (i > 0) {
                const higherBand = sortedBands[i - 1];
                if (band.maxPercentage >= higherBand.minPercentage) {
                    throw ApiError.badRequest(`Overlapping grade boundaries detected between "${band.grade}" (${band.minPercentage}-${band.maxPercentage}) and "${higherBand.grade}" (${higherBand.minPercentage}-${higherBand.maxPercentage}).`);
                }
            }
        }
        let scale = await GradingScale.findOne({ schoolId: sId, isDefault: true, isDeleted: false });
        if (!scale) {
            scale = new GradingScale({
                schoolId: sId,
                isDefault: true,
            });
        }
        if (input.name)
            scale.name = input.name;
        if (input.description !== undefined)
            scale.description = input.description;
        scale.bands = sortedBands;
        await scale.save();
        await this.logAudit(sId, 'UPDATE_GRADING_POLICY', 'GradingScale', actorId, { scaleId: scale._id, bandsCount: scale.bands.length }, ip, ua);
        return scale;
    }
}
